	"os"
)

var data []byte
var pos int

func nextInt() int64 {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(bufio.NewReader(os.Stdin))
	n, minComps, need := nextInt(), nextInt(), nextInt()
	// Close a network as soon as the current run meets both the size and the speed requirement.
	count, length, total := 0, int64(0), int64(0)
	for i := int64(0); i < n; i++ {
		length++
		total += nextInt()
		if length >= minComps && total >= need {
